cd /testbed && python - <<'EOF'
from unittest.mock import patch, mock_open

import pylint.lint.run as run

def fake_is_file(self):
    s = str(self)
    if s.endswith("cpu.cfs_quota_us"):
        return True
    if s.endswith("cpu.cfs_period_us"):
        return True
    if s.endswith("cpu.shares"):
        return True
    return False

def fake_open(path, *args, **kwargs):
    s = str(path)
    if "cpu.cfs_quota_us" in s:
        return mock_open(read_data="-1\n")()
    if "cpu.cfs_period_us" in s:
        return mock_open(read_data="100000\n")()
    if "cpu.shares" in s:
        return mock_open(read_data="2\n")()
    raise FileNotFoundError

with patch("pylint.lint.run.Path.is_file", fake_is_file), patch("builtins.open", fake_open):
    result = run._query_cpu()
    print("avail_cpu:", result)
    assert result == 1, f"expected 1 got {result}"
print("OK")
EOF
